export const gcd=(a,b)=>b?gcd(b,a%b):a;
export function mathSheet({operation='multiply',level='starter',count=12,random=Math.random}={}){count=Math.max(4,Math.min(32,Number(count)||12));const max={starter:10,developing:20,challenge:99}[level]||10;const n=m=>1+Math.floor(random()*m);return Array.from({length:count},(_,i)=>{let a=n(max),b=n(operation==='multiply'?Math.min(max,12):max);let op=operation==='mixed'?['add','subtract','multiply','divide'][i%4]:operation;if(op==='subtract'&&a<b)[a,b]=[b,a];if(op==='divide'){a=b*n(Math.min(max,12));return {q:`${a} ÷ ${b} =`,a:String(a/b)}}if(op==='fractions'){a=n(9);b=n(9)+1;let g=gcd(a,b);return{q:`Simplify ${a*2}/${b*2} =`,a:`${a/g}/${b/g}`}}return{q:`${a} ${{add:'+',subtract:'−',multiply:'×'}[op]||'+'} ${b} =`,a:String(op==='subtract'?a-b:op==='multiply'?a*b:a+b)}})}
export function wordSearch(text,random=Math.random){const words=[...new Set(text.toUpperCase().split(/[\s,;]+/).map(w=>w.replace(/[^A-Z]/g,'')).filter(w=>w.length>=2&&w.length<=12))].slice(0,12);if(!words.length)throw Error('Add at least one word with 2–12 English letters.');const size=14,grid=Array.from({length:size},()=>Array(size).fill('')),placements=[];for(const word of [...words].sort((a,b)=>b.length-a.length)){let placed=false;for(let attempt=0;attempt<500&&!placed;attempt++){const dirs=[[0,1],[1,0],[1,1],[0,-1]], [dr,dc]=dirs[Math.floor(random()*dirs.length)],r=Math.floor(random()*size),c=Math.floor(random()*size);const cells=Array.from(word,(_,i)=>[r+i*dr,c+i*dc]);if(cells.every(([y,x],i)=>y>=0&&y<size&&x>=0&&x<size&&(!grid[y][x]||grid[y][x]===word[i]))){cells.forEach(([y,x],i)=>grid[y][x]=word[i]);placements.push({word,cells});placed=true}}if(!placed)throw Error('Could not place every word. Try generating again with fewer words.')}grid.forEach(row=>row.forEach((v,i)=>{if(!v)row[i]='ABCDEFGHIJKLMNOPQRSTUVWXYZ'[Math.floor(random()*26)]}));return{words,grid,placements}}
export function spellingSheet(text){const words=[...new Set(text.split(/[,\n]+/).map(s=>s.trim()).filter(Boolean))].slice(0,16);if(!words.length)throw Error('Enter your spelling words, separated by commas.');return words.map(w=>({q:w,a:w}))}
